/* Real native25t ->11/12c/12h snapshots; FX uses actual app06 numerical consumers. */
import fs from'node:fs';import assert from'node:assert/strict';import{createNativeHandStrengthConsumer}from'./vecna-hand-strength-consumer-native.mjs';
const cases=[];for(const phase of ['unknown','verified','unattuned']){const f=createNativeHandStrengthConsumer({verified:phase!=='unknown'});if(phase==='unattuned'){f.engine.c.B.inv[0].attuned=false;f.engine.setC(f.engine.project());f.derive()}const score=phase==='verified'?20:14;assert.equal(f.c.D.score.STR,score);assert.equal(f.C.inv.length,1);assert.equal(f.C.inv[0].eq,false);cases.push({phase,build:structuredClone(f.engine.c.B),state:structuredClone(f.engine.c.S),score,modifier:(score-10)/2,attack:f.c.D.atk[0].hit,save:f.c.D.save.STR,skill:f.c.D.skill[f.C.skills.findIndex(row=>row.n==='Athletics')],skillProficiency:f.C.skills.find(row=>row.n==='Athletics').p,skillSource:f.C.skills.find(row=>row.n==='Athletics').src,sheet:structuredClone(f.C)});}fs.writeFileSync(new URL('./vecna-hand-strength-fx.json',import.meta.url),JSON.stringify({provenance:'Actual current Hand only, full nativeGX, actual25t admit/factualattachment, native11/12c/12h; actualapp06 scores/save/skill/attack consumers',cases},null,1)+'\n');console.log(cases.length+' actual native Hand strength snapshots generated');
